def get_neighborhood(grid, r, c, radius=1):
    """Get all cells within a given Manhattan radius"""
    result = []
    for dr in range(-radius, radius+1):
        for dc in range(-radius, radius+1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
