def analyze_demo(input_grid):
    from collections import defaultdict
    rows = len(input_grid)
    cols = len(input_grid[0])

    # For each column, track which rows became 1
    output = [row[:] for row in input_grid]

    # Track changes
    changes = defaultdict(list)  # changes[col] = list of rows

    for r in range(rows):
        for c in range(cols):
            if output[r][c] != input_grid[r][c]:
                if output[r][c] == 1:
                    changes[c].append(r)

    print("Column col c destinations to 1:")
