def solve_v5(grid):
    if not grid or not grid[0]:
        return grid
    h, w = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    from collections import Counter
    color_counts = Counter()
    for row in grid:
        for val in row:
            color_counts[val] += 1

    bg = max(color_counts, key=color_counts.get)
    other_colors = sorted([c for c in color_counts if c != bg], key=lambda x: color_counts[x])
    wall = other_colors[0]  # This becomes 4, and is also the fill color
    marker = other_colors[1]
    fill_color = wall  # Fill uses wall color

    # Step 1: Wall cells become 4
    wall_cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == wall]
    for r,c in wall_cells:
        output[r][c] = 4

    # Step 2: Fill using fill_color
    # Find adjacent wall pairs (horizontal or vertical)

    # Collect wall cells
    wall_by_row = defaultdict(list)
    wall_by_col = defaultdict(list)
    for r,c in wall_cells:
        wall_by_row[r].append(c)
        wall_by_col[c].append(r)

    fills = set()

    # Horizontal pairs (adjacent in same row)
    for r in range(h):
        cols = sorted(wall_by_row[r])
        for i in range(len(cols)-1):
            if cols[i+1] == cols[i] + 1:
                # Found horizontal pair at (r, cols[i]) and (r, cols[i+1])
                pair_right_col = cols[i+1]
                pair_right_row = r

                # Fill: in column pair_right_col, from row pair_right_row+1...
                # to the minimum wall row (if any)
                fill_cols = []
                for rr, cc in wall_cells:
                    if rr > pair_right_row and abs(cc - pair_right_col) <= 2:
                        fill_cols.append(rr)

                for rr in range(pair_right_row + 1, h - 1):
                    if (rr, pair_right_col) not in wall_cells:
                        output[rr][pair_right_col] = fill_color

                i += 1

    # Vertical pairs (adjacent in same column)
    for c in range(w):
        rows = sorted(wall_by_col[c])
        for i in range(len(rows)-1):
            if rows[i+1] == rows[i] + 1:
                # Found vertical pair at (rows[i], c) and (rows[i+1], c)
                pair_bottom_row = rows[i+1]

                # Fill: in row rows[i+1], from column c-1 to c+1...
                for cc in range(c-1, c+2):
                    if 0 <= cc < w and (rows[i+1], cc) not in wall_cells:
                        output[rows[i+1]][cc] = fill_color

                i += 1

    return output

